const config=window.ALMAS_CONFIG;
const products=[{id:'marina-sunset',name:'Marina Sunset',category:'fragrances',type:'Eau de parfum · 50 ml',price:185,art:'photo',image:'assets/marina-sunset-studio.jpg',gallery:['assets/marina-sunset-studio.jpg','assets/marina-sunset-lifestyle.jpg','assets/marina-sunset-garden.jpg'],note:'Lime · Tiaré · Sandalwood',description:'A luminous blend of lime, tiaré and sandalwood. Discover Marina Sunset, presented in our signature 50 ml bottle.'},{id:'caledonian-oud',name:'Caledonian Oud',category:'fragrances',type:'Eau de parfum · 50 ml',price:245,art:'photo',image:'assets/caledonian-oud-studio.jpg',note:'Cardamom · Agarwood · Vanilla',description:'Cardamom, agarwood and vanilla come together in Caledonian Oud. A distinctive fragrance in our signature 50 ml bottle.'},{id:'sage-noir',name:'Sage Noir',category:'fragrances',type:'Eau de parfum · 50 ml',price:185,art:'oud',note:'Bergamot · Sage · Cedarwood',description:'A fresh opening of bergamot unfolds into aromatic sage and a quietly confident cedarwood base.'},{id:'rose-dusk',name:'Rose at Dusk',category:'fragrances',type:'Eau de parfum · 50 ml',price:210,art:'rose',note:'Rose · Amber · Soft musk',description:'Velvety rose meets warm amber and a soft musk trail. An intimate signature for evenings and everyday rituals.'},{id:'oud-heritage',name:'Oud Heritage',category:'fragrances',type:'Eau de parfum · 50 ml',price:245,art:'oud',note:'Oud · Saffron · Sandalwood',description:'A rich, considered blend inspired by Dubai’s love of oud, softened with sandalwood and a touch of saffron.'},{id:'ivory-fabric',name:'The Ivory Edit',category:'fabrics',type:'Unstitched cotton blend · 4 metres',price:145,art:'fabric',color:'#ded8c6',description:'An understated ivory fabric for a clean, timeless shalwar qameez. Unstitched, so you can make the fit your own.'},{id:'sage-fabric',name:'Soft Sage',category:'fabrics',type:'Unstitched cotton blend · 4 metres',price:155,art:'fabric',color:'#b6c0a7',description:'A muted sage fabric with a soft hand and an elegant drape. Designed for thoughtful everyday dressing.'},{id:'charcoal-set',name:'Charcoal Classic',category:'fabrics',type:'Ready-to-wear shalwar qameez',price:295,art:'fabric',color:'#525953',sizes:['S','M','L','XL'],description:'A clean, traditional silhouette in deep charcoal. Includes a kameez and coordinating shalwar.'}];
const $=s=>document.querySelector(s);const money=n=>'AED '+n.toFixed(2);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let cart=[];try{cart=JSON.parse(localStorage.getItem('almas-cart')||'[]').filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20&&['','S','M','L','XL'].includes(x.size))}catch{}let promo=false,shipping='standard',filter='all';
function save(){localStorage.setItem('almas-cart',JSON.stringify(cart));$('#count').textContent=cart.reduce((a,x)=>a+x.qty,0)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2500)}
function art(p){if(p.image)return `<div class="product-art photo"><img src="${p.image}" alt="${escapeHTML(p.name)} — Almas Amjad 50 ml eau de parfum" loading="lazy" width="1254" height="1254"></div>`;return `<div class="product-art ${p.art}" aria-label="Illustrative placeholder for ${p.name}">${p.category==='fragrances'?`<div class="still"><div class="bottle"><div class="cap"></div><div class="label">ALMAS<br>AMJAD<small>${p.name.toUpperCase()}</small></div></div></div>`:`<div class="cloth" style="--cloth:${p.color}"></div>`}<span class="tag">COLLECTION PREVIEW</span></div>`}
function card(p){return `<article class="product-card"><a href="#product/${p.id}">${art(p)}<h3>${p.name}</h3><p>${p.type}</p></a><div class="product-bottom"><span>${money(p.price)}</span>${p.sizes?`<a class="add" href="#product/${p.id}">Choose size ↗</a>`:`<button class="add" data-add="${p.id}">Add to bag +</button>`}</div></article>`}
function totals(){const subtotal=cart.reduce((a,x)=>a+products.find(p=>p.id===x.id).price*x.qty,0),discount=promo?subtotal*.1:0,delivery=shipping==='express'?35:subtotal-discount>=350?0:20;return {subtotal,discount,delivery,total:subtotal-discount+delivery}}
function summary(checkout=false){const t=totals();return `<aside class="panel"><h3>Order summary</h3>${checkout?cart.map(x=>`<p>${products.find(p=>p.id===x.id).name}${x.size?' · '+x.size:''} × ${x.qty}</p>`).join(''):''}<div class="total-row"><span>Subtotal</span><span>${money(t.subtotal)}</span></div>${promo?`<div class="total-row"><span>WELCOME10</span><span>−${money(t.discount)}</span></div>`:''}<div class="field" style="margin-top:20px"><label for="shipping">Delivery within UAE</label><select id="shipping"><option value="standard" ${shipping==='standard'?'selected':''}>Standard · 3–5 business days</option><option value="express" ${shipping==='express'?'selected':''}>Express · 1–2 business days · AED 35</option></select></div><div class="total-row"><span>Shipping</span><span>${t.delivery?money(t.delivery):'Complimentary'}</span></div><div class="total-row total"><span>Total</span><span>${money(t.total)}</span></div><p class="fine">Sample prices and delivery estimates. Tax treatment will be confirmed before live sales.</p><form id="promo" class="inline"><input aria-label="Promo code" name="code" placeholder="Promo code" value="${promo?'WELCOME10':''}"><button class="add">Apply</button></form><p class="fine">Preview offer: WELCOME10 for 10% off.</p>${checkout?'':`<a class="button" style="width:100%;text-align:center" href="#checkout">Continue to checkout →</a>`}</aside>`}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">The art of quiet distinction</div><h1>A signature scent.<br>A timeless<br><em>presence.</em></h1><p>Refined fragrances and distinguished fabrics. Three worlds of inspiration, woven into your everyday.</p><div class="actions"><a class="button" href="#fragrances">Discover fragrances ↗</a><a class="button light" href="#fabrics">Explore fabrics</a></div><p class="fine" style="margin-top:35px;letter-spacing:2px">INSPIRED BY THE UK, DUBAI & PAKISTAN</p></div><a class="hero-art hero-photo" href="#product/marina-sunset" aria-label="Discover Marina Sunset"><img src="assets/marina-sunset-studio.jpg" alt="Marina Sunset by Almas Amjad" fetchpriority="high" width="1254" height="1254"><span class="caption">MARINA SUNSET · EAU DE PARFUM</span></a></section><div class="trust"><span>✧ CONSIDERED COLLECTIONS</span><span>✧ DISTINCTIVE SCENTS</span><span>✧ TIMELESS MENSWEAR</span><span>✧ PERSONAL CUSTOMER CARE</span></div><section class="section"><div class="section-head"><div><span class="eyebrow">Discover your signature</span><h2>The considered edit</h2></div><a class="text-link" href="#fragrances">Explore the collection ↗</a></div><div class="grid">${[products[0],products[1],products[5],products[6]].map(card).join('')}</div></section><section class="story-banner"><div><span class="eyebrow">Three places. One point of view.</span><h2>Rooted in heritage.<br>Refined for today.</h2></div><div><p>British restraint. Dubai’s warmth. Pakistan’s rich tradition of dress. Almas Amjad brings these influences together in fragrances and menswear with an unmistakably personal character.</p><a class="button light" href="#about">Read our story ↗</a></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">A wardrobe with intention</span><h2>Fabric, with feeling.</h2><p>Soft tones. Beautiful drape. A foundation for your personal style.</p></div><a class="button light" href="#fabrics">Discover menswear ↗</a></div></section>`}
const policies={privacy:['Privacy Policy','We respect your privacy. This preview stores only your shopping bag in your browser. Checkout form details are not retained by the preview site.','Contacting us','If you choose an email inquiry, your email application prepares a message for waqasamjadrana@outlook.com. You decide whether to send it.','Live checkout','When live payments are enabled, the selected payment provider will process payment data on its hosted checkout. We will use order and contact information to handle purchases and customer care. A final policy identifying processors, retention periods and customer rights must be approved before trading.'],terms:['Terms & Conditions','This website currently presents a sample collection. Products, prices, imagery and availability are illustrative and do not constitute an accepted order.','Orders and payments','Preview confirmations are not sales contracts or proof of payment. Live orders require availability confirmation and a successful payment through the configured provider.','Product information','Fragrance notes, fabric composition, sizes and images must be checked against the final catalogue before launch. Consumer rights apply according to the final business jurisdiction. These draft terms require business review.'],shipping:['Shipping & Returns','Our launch delivery plan focuses on the UAE. Contact us for UK and Pakistan inquiries; international checkout is not yet offered.','Proposed UAE delivery','Standard: AED 20, complimentary from AED 350 after discounts, estimated 3–5 business days. Express: AED 35, estimated 1–2 business days. These are sample rates awaiting courier confirmation.','Returns and exchanges','Contact waqasamjadrana@outlook.com before returning a product. The final return window, eligibility for opened fragrances, cut fabric and custom tailoring, and refund procedure will be published before live sales. These draft policies do not limit statutory rights.']};
function render(){const route=(location.hash.slice(1)||'home').split('/'),page=route[0];document.title=(page==='home'?'Almas Amjad':page[0].toUpperCase()+page.slice(1)+' | Almas Amjad')+' – Fragrances & Fabrics';let html='';if(page==='home')html=home();else if(['fragrances','fabrics'].includes(page)){const list=products.filter(p=>p.category===page&&(filter==='all'||(filter==='ready'?p.sizes:!p.sizes)));html=`<div class="page"><div class="eyebrow">The Almas Amjad collection</div><h1>${page==='fragrances'?'Fragrances':'Fabrics & Menswear'}</h1><p class="intro">${page==='fragrances'?'Scents that linger in memory. Discover a signature for each mood, moment and expression.':'Understated fabrics and classic shalwar qameez, inspired by the enduring elegance of Pakistani dress.'}</p>${page==='fabrics'?`<div class="filters">${[['all','All pieces'],['unstitched','Unstitched fabrics'],['ready','Ready-to-wear']].map(([v,n])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${n}</button>`).join('')}</div>`:''}<p class="fine">Illustrative catalogue · sample prices in AED</p><div class="grid">${list.map(card).join('')}</div></div>`}else if(page==='product'){const p=products.find(x=>x.id===route[1]);if(!p){location.hash='home';return}html=`<div class="page"><div class="breadcrumb"><a href="#${p.category}">${p.category==='fabrics'?'Fabrics & Menswear':'Fragrances'}</a> / ${p.name}</div><div class="detail"><div>${art(p)}${p.gallery?`<div class="photo-gallery" aria-label="${escapeHTML(p.name)} photo gallery">${p.gallery.map((src,i)=>`<a href="${src}" target="_blank" rel="noopener" aria-label="View ${escapeHTML(p.name)} photograph ${i+1}"><img src="${src}" alt="${escapeHTML(p.name)} ${['studio','lifestyle','garden'][i]} photograph" loading="lazy" width="1254" height="1254"></a>`).join('')}</div>`:''}</div><div><span class="eyebrow">Almas Amjad · ${p.category}</span><h1>${p.name}</h1><p>${p.type}</p><h3>${money(p.price)}</h3><p class="fine">Preview price · Final pricing to be confirmed.</p><p>${p.description}</p>${p.note?`<p class="eyebrow">${p.note}</p>`:''}${p.sizes?`<div class="field"><label for="size">Select size</label><select id="size">${p.sizes.map(s=>`<option>${s}</option>`).join('')}</select></div><p class="fine">Sample sizing: S chest 38–40 in, M 40–42, L 42–44, XL 44–46. Confirm final measurements before ordering.</p>`:''}<div class="actions"><input id="product-qty" type="number" min="1" max="20" value="1" aria-label="Quantity" style="width:80px"><button class="button" data-add="${p.id}" data-detail="true">Add to bag →</button></div><p class="notice">Collection preview. Illustrations and specifications will be replaced with final product details before launch.</p><p class="fine">UAE delivery available at launch. <a class="text-link" href="#shipping">Delivery & returns</a></p><a class="text-link" href="#contact">Ask about this piece ↗</a></div></div></div>`}else if(page==='cart'||page==='checkout'){html=`<div class="page"><div class="breadcrumb"><a href="#home">Home</a> / Shopping bag${page==='checkout'?' / Checkout':''}</div><h1>${page==='cart'?'Your shopping bag':'The final details'}</h1>${!cart.length?`<div class="empty"><h2>Your bag awaits.</h2><p>Discover something that feels like you.</p><a class="button" href="#fragrances">Explore the collection</a></div>`:`<div class="split"><div>${page==='cart'?cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-row">${art(p)}<div><a href="#product/${p.id}"><h3>${p.name}</h3></a><p>${p.type}${x.size?' · Size '+x.size:''}</p><div class="qty"><button data-qty="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div></div><div>${money(p.price*x.qty)}<br><button class="remove" data-remove="${i}">Remove</button></div></div>`}).join(''):`<form id="checkout"><h3>Contact & delivery</h3><div class="form-grid"><div class="field"><label for="first">First name</label><input id="first" name="first" required autocomplete="given-name" maxlength="80"></div><div class="field"><label for="last">Last name</label><input id="last" name="last" required autocomplete="family-name" maxlength="80"></div></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" required autocomplete="tel" placeholder="+971"></div><div class="field"><label for="address">Street address / building / apartment</label><input id="address" name="address" required autocomplete="street-address" maxlength="200"></div><div class="form-grid"><div class="field"><label for="city">City / Emirate</label><select id="city" name="city">${['Dubai','Abu Dhabi','Sharjah','Ajman','Fujairah','Ras Al Khaimah','Umm Al Quwain'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="country">Country</label><input id="country" name="country" value="United Arab Emirates" readonly></div></div><div class="field"><label for="notes">Delivery notes (optional)</label><textarea id="notes" name="notes" rows="3" maxlength="500"></textarea></div><h3>Payment</h3><p class="notice">${config.checkoutEndpoint?'You will continue to a secure hosted payment page.':'Preview checkout · No payment is collected and no order is sent. Live payment setup is pending.'}</p><label class="check"><input type="checkbox" required><span>I have read the <a class="text-link" href="#terms">terms</a> and <a class="text-link" href="#privacy">privacy policy</a>.</span></label><button class="button" id="pay" style="margin-top:25px">${config.checkoutEndpoint?'Continue to secure payment →':'Preview order confirmation →'}</button><p id="checkout-error" role="alert"></p></form>`}</div>${summary(page==='checkout')}</div>`}</div>`}else if(page==='confirmation'){let order;try{order=JSON.parse(sessionStorage.getItem('almas-preview-order'))}catch{}html=`<div class="page"><div class="empty"><div class="order-icon">✧</div><div class="eyebrow">${order?'Preview complete':'Order status'}</div><h1>${order?'A beautiful choice.':'Payment verification pending.'}</h1><p>${order?'Your preview order is ready to review. No payment was taken or order submitted.':'A redirect alone does not confirm payment. Contact the boutique to check your order.'}</p>${order?`<p>Preview reference: ${escapeHTML(order.ref)}</p><div class="panel" style="max-width:450px;margin:25px auto">${order.items.map(x=>`<div class="total-row"><span>${escapeHTML(x.name)}${x.size?' · '+escapeHTML(x.size):''} × ${x.qty}</span><span>${money(x.price*x.qty)}</span></div>`).join('')}<div class="total-row total"><span>Total</span><span>${money(order.total)}</span></div></div><a class="button" href="${emailLink('Almas Amjad collection inquiry',`I would like to inquire about preview ${order.ref}.\n${order.items.map(x=>`${x.name} ${x.size} × ${x.qty}`).join('\n')}\nEstimated total: ${money(order.total)}`)}">Inquire about these pieces ↗</a>`:''}<div class="actions" style="justify-content:center"><a class="button light" href="#home">Return to the boutique</a></div></div></div>`}else if(page==='about'){html=`<div class="page"><div class="eyebrow">Our story</div><h1>Three worlds.<br>One enduring signature.</h1><div class="split"><div><h2>Elegance, made personal.</h2><p>Almas Amjad is a fragrance and menswear brand inspired by the places and traditions that shape us: the considered style of the UK, the expressive spirit of Dubai, and the textile heritage of Pakistan.</p><p>We believe the most memorable details speak softly. A scent that becomes familiar. A fabric that feels right. A silhouette that gives you confidence without demanding attention.</p><p>Our collections bring together warm fragrance notes, restrained palettes and timeless dress. Each piece invites you to create a signature that is entirely your own.</p><a class="button" href="#fragrances">Find your signature ↗</a></div><div class="panel"><span class="eyebrow">Our point of view</span><h3>Considered, always.</h3><p>Quiet colour. Thoughtful detail. A connection to heritage, with room for individuality.</p><h3>A personal approach.</h3><p>For gifting, fabric choices or fragrance recommendations, speak with us directly.</p><a class="text-link" href="#contact">Contact the boutique ↗</a></div></div></div>`}else if(page==='contact'){html=`<div class="page"><div class="eyebrow">Personal customer care</div><h1>Let’s find your signature.</h1><div class="split"><form id="contact"><div class="field"><label for="contact-name">Your name</label><input id="contact-name" name="name" required maxlength="100"></div><div class="field"><label for="contact-email">Email address</label><input id="contact-email" name="email" type="email" required></div><div class="field"><label for="subject">How can we help?</label><select id="subject" name="subject"><option>Fragrance recommendation</option><option>Fabrics & sizing</option><option>Order inquiry</option><option>Gifting & general inquiry</option></select></div><div class="field"><label for="message">Your message</label><textarea id="message" name="message" required rows="5" maxlength="3000"></textarea></div><button class="button">Prepare email inquiry ↗</button><p class="fine">Opens your email application with a draft. Please send it there to deliver your inquiry.</p></form><div class="panel"><h3>A conversation, thoughtfully.</h3><p>Contact us for collection details, personal recommendations and delivery inquiries.</p><a class="text-link" href="mailto:${config.contactEmail}">${config.contactEmail}</a><h3>WhatsApp</h3>${config.whatsappNumber?`<a class="button light" href="https://wa.me/${config.whatsappNumber.replace(/\D/g,'')}" target="_blank" rel="noopener">Chat on WhatsApp ↗</a>`:'<p>WhatsApp inquiries will be available once our boutique number is confirmed. In the meantime, please email us.</p>'}<p class="fine">UK · Dubai · Pakistan inspired</p></div></div></div>`}else if(policies[page]){const p=policies[page];html=`<div class="page policy"><div class="eyebrow">Customer care · Draft for launch review</div><h1>${p[0]}</h1><p>${p[1]}</p><h2>${p[2]}</h2><p>${p[3]}</p><h2>${p[4]}</h2><p>${p[5]}</p><a class="text-link" href="#contact">Contact customer care ↗</a></div>`}else{html=`<div class="page empty"><h1>Page not found</h1><a class="button" href="#home">Return home</a></div>`}$('#app').innerHTML=html;save();bind()}
function emailLink(subject,body){return 'mailto:'+config.contactEmail+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}
function bind(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const p=products.find(p=>p.id===b.dataset.add),size=p.sizes?$('#size')?.value||'M':'',qty=b.dataset.detail?Number($('#product-qty').value):1;if(!Number.isInteger(qty)||qty<1||qty>20){toast('Choose a quantity between 1 and 20.');return}const item=cart.find(x=>x.id===p.id&&x.size===size);if(item){if(item.qty+qty>20){toast('Maximum 20 per item.');return}item.qty+=qty}else cart.push({id:p.id,size,qty});save();toast(p.name+' added to your bag')});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{cart[b.dataset.qty].qty=Math.max(1,Math.min(20,cart[b.dataset.qty].qty+Number(b.dataset.delta)));save();render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);save();render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});const updateSummary=()=>{const values=$('#checkout')?new FormData($('#checkout')):null;const agreed=$('#checkout input[type=checkbox]')?.checked;render();if(values){for(const [k,v]of values){const el=$(`#checkout [name="${k}"]`);if(el)el.value=v}$('#checkout input[type=checkbox]').checked=agreed}};if($('#shipping'))$('#shipping').onchange=e=>{shipping=e.target.value;updateSummary()};if($('#promo'))$('#promo').onsubmit=e=>{e.preventDefault();const code=new FormData(e.target).get('code').trim().toUpperCase();if(code!=='WELCOME10'){toast('This promo code is not valid.');return}promo=true;updateSummary();toast('10% preview discount applied')};if($('#contact'))$('#contact').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);location.href=emailLink('Almas Amjad: '+d.get('subject'),`Name: ${d.get('name')}\nEmail: ${d.get('email')}\n\n${d.get('message')}`)};if($('#checkout'))$('#checkout').onsubmit=async e=>{e.preventDefault();const customer=Object.fromEntries(new FormData(e.target));if(!config.checkoutEndpoint){sessionStorage.setItem('almas-preview-order',JSON.stringify({ref:'AA-PREVIEW-'+Date.now().toString(36).toUpperCase(),items:cart.map(x=>({...x,name:products.find(p=>p.id===x.id).name,price:products.find(p=>p.id===x.id).price})),...totals()}));location.hash='confirmation';return}$('#pay').disabled=true;try{const response=await fetch(config.checkoutEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart,shipping,promo:promo?'WELCOME10':'',customer})});if(!response.ok)throw Error('Checkout could not be started. Please try again or contact us.');const data=await response.json();const url=new URL(data.url);if(url.protocol!=='https:')throw Error('Invalid secure checkout URL.');location.assign(url.href)}catch(err){$('#checkout-error').textContent=err.message;$('#pay').disabled=false}}}
window.addEventListener('hashchange',()=>{filter='all';render();window.scrollTo(0,0)});$('#year').textContent=new Date().getFullYear();render();

